#pragma once
#include "../../support.hpp"
#include "hash.hpp"
namespace algs {
template<class K,class V>class HashTable{using Entry=std::pair<K,V>;std::vector<std::vector<Entry>>buckets;int count=0;std::function<std::uint32_t(const K&)>hasher;double maxLoad;std::vector<Entry>&bucket(const K&k){return buckets[hasher(k)%buckets.size()];}const std::vector<Entry>&bucket(const K&k)const{return buckets[hasher(k)%buckets.size()];}void resize(int n){auto all=entries();buckets.assign(n,{});for(auto&e:all)bucket(e.first).push_back(e);}public:explicit HashTable(std::function<std::uint32_t(const K&)>h=defaultHasher<K>,int capacity=16,double load=0.75):buckets(std::max(1,capacity)),hasher(h),maxLoad(load){}int size()const{return count;}int capacity()const{return int(buckets.size());}HashTable&set(K k,V v){auto&b=bucket(k);for(auto&e:b)if(e.first==k){e.second=v;return *this;}b.emplace_back(k,v);++count;if(double(count)/buckets.size()>maxLoad)resize(int(buckets.size())*2);return *this;}std::optional<V>get(const K&k)const{for(auto&e:bucket(k))if(e.first==k)return e.second;return {};}bool has(const K&k)const{for(auto&e:bucket(k))if(e.first==k)return true;return false;}bool erase(const K&k){auto&b=bucket(k);for(auto it=b.begin();it!=b.end();++it)if(it->first==k){b.erase(it);--count;return true;}return false;}void clear(){for(auto&b:buckets)b.clear();count=0;}std::vector<Entry>entries()const{std::vector<Entry>r;for(auto&b:buckets)r.insert(r.end(),b.begin(),b.end());return r;}std::vector<K>keys()const{std::vector<K>r;for(auto&e:entries())r.push_back(e.first);return r;}std::vector<V>values()const{std::vector<V>r;for(auto&e:entries())r.push_back(e.second);return r;}};
}
